(() => {
                        const records = (checkinHistory ?? [])
                          .filter(r => !r.deleted && r.weight != null && r.weight > 0)
                          .sort((a, b) => a.date.localeCompare(b.date))
                          .slice(-7);
                        if (records.length < 2) return null;
                        const weights = records.map(r => r.weight);
                        const minW = Math.min(...weights);
                        const maxW = Math.max(...weights);
                        const range = maxW - minW || 1;
                        const chartHeight = 50;
                        const labelHeight = 20;
                        const totalHeight = chartHeight + labelHeight;
                        const chartWidth = BANNER_WIDTH - 80;
                        const stepX = chartWidth / (records.length - 1);

                        return (
                          <View style={{ position: 'relative', height: totalHeight }}>
                            {/* Line segments */}
                            {records.map((r, i) => {
                              if (i === 0) return null;
                              const prevR = records[i - 1];
                              const x1 = (i - 1) * stepX;
                              const y1 = chartHeight - ((prevR.weight - minW) / range) * (chartHeight - 15);
                              const x2 = i * stepX;
                              const y2 = chartHeight - ((r.weight - minW) / range) * (chartHeight - 15);
                              const length = Math.sqrt((x2 - x1) ** 2 + (y2 - y1) ** 2);
                              const angle = Math.atan2(y2 - y1, x2 - x1) * (180 / Math.PI);
                              return (
                                <View
                                  key={`line-${i}`}
                                  style={{
                                    position: 'absolute',
                                    left: x1,
                                    top: y1,
                                    width: length,
                                    height: 2,
                                    backgroundColor: 'rgba(255,255,255,0.8)',
                                    transform: [{ rotate: `${angle}deg` }],
                                    transformOrigin: '0 0',
                                  }}
                                />
                              );
                            })}
                            {/* Data points with weight labels */}
                            {records.map((r, i) => {
                              const x = i * stepX;
                              const y = chartHeight - ((r.weight - minW) / range) * (chartHeight - 15);
                              const isLast = i === records.length - 1;
                              return (
                                <React.Fragment key={`point-${i}`}>
                                  {/* Weight value above point */}
                                  <Text style={{
                                    position: 'absolute',
                                    left: x - 15,
                                    top: y - 18,
                                    fontSize: FONT_SMALL(),
                                    color: '#fff',
                                    fontWeight: isLast ? '700' : '500',
                                    width: 30,
                                    textAlign: 'center',
                                  }}>
                                    {String(r.weight)}
                                  </Text>
                                  {/* Point */}
                                  <View style={{
                                    position: 'absolute',
                                    left: x - 5,
                                    top: y - 5,
                                    width: isLast ? 12 : 8,
                                    height: isLast ? 12 : 8,
                                    borderRadius: isLast ? 6 : 4,
                                    backgroundColor: isLast ? '#fff' : 'rgba(255,255,255,0.7)',
                                  }} />
                                </React.Fragment>
                              );
                            })}
                            {/* Date labels at bottom */}
                            {records.map((r, i) => (
                              <Text
                                key={`label-${i}`}
                                style={{
                                  position: 'absolute',
                                  left: i * stepX - 12,
                                  top: chartHeight + 4,
                                  fontSize: FONT_SMALL(),
                                  color: 'rgba(255,255,255,0.8)',
                                  width: 24,
                                  textAlign: 'center',
                                }}
                              >
                                {r.date.slice(8)}
                              </Text>
                            ))}
                          </View>
                        );
                      })

Animated.timing(fadeAnim, {
      toValue: 0,
      duration: TRANSITION_DURATION / 2,
      useNativeDriver: true,
    }).start

Animated.timing(fadeAnim, {
        toValue: 1,
        duration: TRANSITION_DURATION / 2,
        useNativeDriver: true,
